 CREATE OR REPLACE FUNCTION public.listintakedetails_neq1(securityusersid character varying, status character varying, pagenumber bigint, pagesize bigint, intakeno character varying, bpreintake boolean, sortcolumn character varying, sortorder character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                           
  RETURNS TABLE(totalcount bigint, id integer, intakenumber character varying, cpsresponse character varying, datereceived timestamp without time zone, timereceived timestamp without time zone, narrative text, raname character varying, entityname character varying, cruworkername character varying, isreview boolean, issupervisor boolean, datesubmitted timestamp without time zone, dateclosed timestamp without time zone, remarks text, reviewstatus character varying, disposition character varying, intakestatus character varying, timeleft character varying, jsondata jsonb, updateddate timestamp without time zone, agencycode character varying, canreopen integer, ispreintake boolean, clwstatus integer)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
   DECLARE    v_status int;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
         v_UserSID character varying;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
         v_activeflag int;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
         v_pageoffset int;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
         v_pagenumber int;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                 v_statustext character varying;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
     v_activeflag:= 1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
     v_UserSID:= securityusersid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
     v_pagenumber := pagenumber-1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
     v_pageoffset = v_pagenumber * pagesize;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
     v_statustext:= status;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
    RAISE NOTICE 'v_status%',sortcolumn;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
        RAISE NOTICE 'v_status%',sortorder;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
  If (status='pending') THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
         v_status:=1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
  ELSIF  (status='reopen') THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
         v_status:=7;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
      v_activeflag:= 0;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
   ELSIF  (status='approved') THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
         --v_status:=3;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
  v_status:=8;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
    ELSIF  (status='closed') THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
         v_status:=8;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
  ELSIF  (status='assigned') THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
         v_status:=10;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
 end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
   RAISE NOTICE 'v_status%',v_status;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
     RAISE NOTICE 'v_activeflag%',v_activeflag;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
 /*Get Individual Intake details */                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
     IF (LOWER(status)='intake') THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
      RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
          SELECT  count(1)  over(),IDAS.id,IDAS.IntakeNumber ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
           cast(case DAS.iscps when true then 'CPS' when false then 'Non CPS' else '' end  as character varying),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
             IDAS.DateRecieved,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
             (to_char(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                         IDAS.TimeRecieved ::timestamp without  time zone,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                 'YYYYMMDD"T"HH24MISS"Z"' )::timestamptz)::timestamp without time zone,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
             IDAS.Narrative, IDAS.RAName,  IDAS.EntityName,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
             cast(IDAS.CRUWorkerName  as character varying) ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
             false,false ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
             (select max(insertedon ) from routing where objectid= IDAS.IntakeNumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
              and isreviewrequest =true and eventcode ='INTR'),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
             IDAS.insertedon ::timestamp ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
             cast ('' as text) ,cast (DAS.typedescription as character varying) ,dispositiondescription,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
             cast( statusdescription as character varying),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                cast( case DAS.submitteddate when null then '' else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 case                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                     when  age(  now() at time zone 'utc' )  - age(DAS.submitteddate  + time '02:00' )  > '0:00' then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                 cast( age( now() at time zone 'utc' )  - age(  DAS.submitteddate  + time '02:00' ) as character varying(5))                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                      else 'Overdue' end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 end as character varying),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 (case when (status1 in (2,8))                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                         then (select ISS.jsondata as js from intakesnapshot ISS where ISS.IntakeNumber = intakeno  limit 1)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                         else IDAS.jsondata end)::jsonb,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
              IDAS.updatedon ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
             '':: character varying,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
             0, IDAS.ispreintake  , IDAS.clwstatus                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
         FROM (select /*(to_char(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                         submitteddate::timestamp,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                 'YYYYMMDD"T"HH24MISS"Z"' )::timestamptz)::timestamp without time zone submitteddate*/                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
              submitteddate , DAS1.iscps ,DAS1.status as status1,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
               DAS1.IntakeNumber,rts.typedescription from  IntakeDAStatus DAS1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
               LEFT JOIN routingstatustype RTs ON RTs.sequencenumber = DAS1.status                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                 and rts.activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
              ) DAS inner join IntakeDAStaging IDAS                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
         ON IDAS.IntakeNumber =DAS.IntakeNumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
         WHERE IDAS.IntakeNumber like intakeno||'%'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
         AND  IDAS.Activeflag = 1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
    else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
    IF (v_status=7) THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
         RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                SELECT  count(1)  over(),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                 IDAS.id,IDAS.IntakeNumber ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                 cast(case IDS.iscps when true then 'CPS' when false then 'Non CPS' else '' end  as character varying),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                         IDAS.DateRecieved,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 (to_char(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                         IDAS.TimeRecieved::timestamp without  time zone,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                 'YYYYMMDD"T"HH24MISS"Z"' )::timestamptz)::timestamp without time zone,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                 IDAS.Narrative, IDAS.RAName, IDAS.EntityName,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                 cast(up.lastname ||', '|| up.firstname as character varying) ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                 coalesce(r.isreviewrequest,false),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 coalesce(rt.isupervisor,false) ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 r.insertedon,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                 /*(to_char(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                          r.updatedon::timestamp,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                                                          'YYYYMMDD"T"HH24MISS"Z"' )::timestamptz)::timestamp without time zone*/                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 r.updatedon ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                  r.remarks,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                 cast(case lower(coalesce(rts.typedescription,'Pending'))                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                     when 'pending' then 'Draft' else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                 case when tosecurityusersid = IDAS.intakeuser and r.routingstatustypeid = 1 then 'Reopen' else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                     rts.typedescription end end as character varying)  ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                 dispositiondescription,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 statusdescription,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 cast( case r.insertedon when null then '' else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                 case                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                     when  age(  now() at time zone 'utc')  - age(r.insertedon  + time '02:00' )  > '0:00' then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                 cast( age( now() at time zone 'utc')  - age(  r.insertedon  + time '02:00' ) as character varying(5))                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                      else 'Overdue' end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 end as character varying),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 null::jsonb ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                 IDAS.updatedon ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 IDS.teamtypekey ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                 0, IDAS.ispreintake, IDAS.clwstatus                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
             FROM IntakeDAStaging IDAS                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
             INNER JOIN IntakeDAStatus IDS on IDS.intakenumber = IDAS.intakenumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
             and ids.status =v_status                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
             LEFT JOIN  routing r ON r.objectid = IDAS.intakenumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 AND (r.activeflag =1 or r.activeflag = v_activeflag)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                 and r.eventcode ='INTR'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
             LEFT JOIN routingstatustype RTs ON RTs.sequencenumber = r.routingstatustypeid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                 and rts.activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
             LEFT JOIN teammemberroletype rt on rt.roletypekey = r.toroleid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 AND rt.activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
             INNER JOIN userprofile up on up.securityusersid = IDAS.CRUWorkerName                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
             WHERE IDAS.IntakeNumber like intakeno||'%'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                 AND (case v_status when 1 then lower(IDAS.Status) = 'pending' else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 r.routingstatustypeid =v_status end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                 OR case IDAS.intakeuser  when v_UserSID then r.routingstatustypeid =6                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                      else  r.routingstatustypeid =v_status end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                     )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                 AND  IDAS.Activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                 AND ( coalesce(r.tosecurityusersid,IDAS.intakeuser)  =v_UserSID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                    OR  case right(fromroleid,2) when 'IW' then IDAS.InsertedBy   =v_UserSID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                         else r.tosecurityusersid  =v_UserSID  end )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                           ORDER BY                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                  ( CASE sortorder when 'asc' then CASE sortcolumn when 'receiveddate' then cast( IDAS.TimeRecieved    as character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                  when 'submittedworker' then  cast(up.lastname ||', '|| up.firstname as character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                  ELSE IDAS.intakenumber end  ELSE cast( IDAS.EntityName  as character varying)  end)  asc,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                   ( CASE sortorder when 'desc' then CASE sortcolumn when 'receiveddate' then cast( IDAS.TimeRecieved    as character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                  when 'submittedworker' then  cast(up.lastname ||', '|| up.firstname as character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                  ELSE IDAS.intakenumber end  ELSE cast( IDAS.EntityName  as character varying)  end )  desc                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
             LIMIT pagesize OFFSET v_pageoffset ;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
 ELSIF (v_status =8) THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
    RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                SELECT  count(1)  over(),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                 IDAS.id,IDAS.IntakeNumber ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                 cast(case ITDS.iscps when true then 'CPS' when false then 'Non CPS' else '' end  as character varying),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                         IDAS.DateRecieved,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 (to_char(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                         IDAS.TimeRecieved::timestamp without  time zone,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                 'YYYYMMDD"T"HH24MISS"Z"' )::timestamptz)::timestamp without time zone,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                 IDAS.Narrative, IDAS.RAName, IDAS.EntityName,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                 cast(up.lastname ||', '|| up.firstname as character varying) ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                 coalesce(r.isreviewrequest,false),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 coalesce(rt.isupervisor,false) ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 r.insertedon, /*(to_char(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                          r.updatedon::timestamp,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                                                          'YYYYMMDD"T"HH24MISS"Z"' )::timestamptz)::timestamp without time zone  ,*/                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                 r.updatedon,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                 r.remarks,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 cast(case lower(coalesce(rts.typedescription,'Pending'))                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                     when 'pending' then 'Draft' else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                 case when tosecurityusersid = IDAS.intakeuser and r.routingstatustypeid = 1 then 'Reopen' else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                     rts.typedescription end end as character varying)  ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                 dispositiondescription,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 statusdescription,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 cast( case r.insertedon when null then '' else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                 case                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                     when  age(  now()  at time zone 'utc')  - age(r.insertedon + time '02:00' )  > '0:00' then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                 cast( age( now() at time zone 'utc')  - age(  r.insertedon + time '02:00' ) as character varying(5))                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                      else 'Overdue' end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 end as character varying),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                  IDAS.jsondata,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                 IDAS.updatedon ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 ITDS.teamtypekey ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 case  when ITDS.teamtypekey = 'DJS' and lower(rts.typedescription)='closed' then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 case coalesce(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                     (select count(1) from IntakeAppeal IP where IP.intakenumber =IDAS.intakenumber ),0)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                     when 0 then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                         case when   now()::date -  (r.updatedon :: date + 30 ):: date >0 then 0                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                         else 1 end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                      else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                      2 end else 0  end,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                          IDAS.ispreintake, IDAS.clwstatus                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
             FROM IntakeDAStaging IDAS                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
             INNER JOIN intakeDAStatus ITDS on ITDS.intakenumber = IDAS.intakenumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
             LEFT JOIN  routing r ON r.objectid = IDAS.intakenumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 AND (r.activeflag =1 or r.activeflag = v_activeflag)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                 and r.eventcode ='INTR'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
             LEFT JOIN routingstatustype RTs ON RTs.sequencenumber = r.routingstatustypeid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                 and rts.activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
             LEFT JOIN teammemberroletype rt on rt.roletypekey = r.toroleid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 AND rt.activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
             INNER JOIN userprofile up on up.securityusersid = IDAS.CRUWorkerName                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
             WHERE IDAS.IntakeNumber like intakeno||'%'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                 AND  r.routingstatustypeid IN (8,2)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                 AND  IDAS.Activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                 AND ( coalesce(r.tosecurityusersid,IDAS.intakeuser)  =v_UserSID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                    OR  case right(fromroleid,2) when 'IW' then IDAS.InsertedBy   =v_UserSID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                         else r.tosecurityusersid  =v_UserSID  end )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                   ORDER BY                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                  ( CASE sortorder when 'asc' then CASE sortcolumn when 'receiveddate' then cast( IDAS.TimeRecieved    as character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                  when 'submittedworker' then  cast(up.lastname ||', '|| up.firstname as character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                  ELSE IDAS.intakenumber end  ELSE cast( IDAS.EntityName  as character varying)  end)  asc,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                   ( CASE sortorder when 'desc' then CASE sortcolumn when 'receiveddate' then cast( IDAS.TimeRecieved    as character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                  when 'submittedworker' then  cast(up.lastname ||', '|| up.firstname as character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                  ELSE IDAS.intakenumber end  ELSE cast( IDAS.EntityName  as character varying)  end )  desc                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                  LIMIT pagesize OFFSET v_pageoffset ;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
   ELSE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                         SELECT  count(1)  over(), * from                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                ((SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 IDAS.id,IDAS.IntakeNumber ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                 cast(case ITDS.iscps when true then 'CPS' when false then 'Non CPS' else '' end  as character varying),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                         IDAS.DateRecieved,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 (to_char(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                         IDAS.TimeRecieved::timestamp without  time zone,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                 'YYYYMMDD"T"HH24MISS"Z"' )::timestamptz)::timestamp without time zone,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                 IDAS.Narrative, IDAS.RAName, IDAS.EntityName,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                 cast(up.lastname ||', '|| up.firstname as character varying)   ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 coalesce(r.isreviewrequest,false),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 coalesce(rt.isupervisor,false) ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 r.insertedon,r.updatedon ,r.remarks,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                 cast(case lower(coalesce(rts.typedescription,'Pending'))                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                     when 'pending' then case ITDS.status when 10 then 'Assigned' else 'Draft' end  else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 case when tosecurityusersid = IDAS.intakeuser and r.routingstatustypeid = 1 then 'Reopen' else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                     rts.typedescription end end as character varying)  ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                 dispositiondescription,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 statusdescription,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                  cast( case r.insertedon when null then '' else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                 case                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                     when  age(  now()at time zone 'utc')  - age(r.insertedon + time '02:00' )  > '0:00' then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                 cast( age( now() at time zone 'utc')  - age(  r.insertedon + time '02:00' ) as character varying(5))                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                      else   cast( age( now() at time zone 'utc')  - age(  r.insertedon  + time '02:00' ) as character varying(5)) end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                 end as character varying),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 /*cast( case r.insertedon when null then '' else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 case                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                     when  age(  now()::TIMESTAMP)  - age(r.insertedon::TIMESTAMP + interval '2h' )  > '0:00' then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                 cast( age( now()::TIMESTAMP)  - age(  r.insertedon::TIMESTAMP + interval '2h' ) as character varying(5))                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                      else 'Overdue' end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 end as character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                 */                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 null::jsonb ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                 IDAS.updatedon ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 ITDS.teamtypekey ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 0, IDAS.ispreintake, IDAS.clwstatus                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
             FROM IntakeDAStaging IDAS                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
             INNER JOIN intakeDAStatus ITDS on ITDS.intakenumber = IDAS.intakenumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
             LEFT JOIN  routing r ON r.objectid = IDAS.intakenumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 AND (r.activeflag =1 or r.activeflag = v_activeflag)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                 and r.eventcode ='INTR'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
             LEFT JOIN routingstatustype RTs ON RTs.sequencenumber = r.routingstatustypeid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                 and rts.activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
             LEFT JOIN teammemberroletype rt on rt.roletypekey = r.toroleid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 AND rt.activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
             LEFT JOIN userprofile up on up.securityusersid = IDAS.CRUWorkerName                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
             WHERE IDAS.IntakeNumber like intakeno||'%'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                 AND (case v_status when 1 then lower(IDAS.Status) = 'pending' else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 r.routingstatustypeid =v_status end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                 OR case IDAS.intakeuser  when v_UserSID then r.routingstatustypeid =6                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                      else  r.routingstatustypeid =v_status end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                     )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                 AND  IDAS.Activeflag = 1 and coalesce(IDAS.ispreintake,false) = false                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                 AND ( coalesce(r.tosecurityusersid,IDAS.intakeuser)  =v_UserSID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                    OR  case right(fromroleid,2) when 'IW' then IDAS.InsertedBy   =v_UserSID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                         else r.tosecurityusersid  =v_UserSID  end )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                 ORDER BY                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                  ( CASE sortorder when 'asc' then CASE sortcolumn when 'receiveddate' then cast( IDAS.TimeRecieved    as character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                  when 'submittedworker' then  cast(up.lastname ||', '|| up.firstname as character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                     when 'intakenumber' then IDAS.intakenumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                  ELSE cast(IDAS.id as   character varying) end  ELSE cast( IDAS.EntityName  as character varying)  end)  asc,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                   ( CASE sortorder when 'desc' then CASE sortcolumn                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                    when 'receiveddate' then cast( IDAS.TimeRecieved    as character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                         when 'submittedworker' then  cast(up.lastname ||', '|| up.firstname as character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                    when 'intakenumber' then IDAS.intakenumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                  ELSE cast(IDAS.id as   character varying) end  ELSE cast( IDAS.EntityName  as character varying)  end )  desc                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                  )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                  union all                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                  (select   1,IDAS.IntakeNumber ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 cast(case ITDS.iscps when true then 'CPS' when false then 'Non CPS' else '' end  as character varying),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                         IDAS.reporteddate,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 (to_char(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                         IDAS.reportedtime::timestamp without  time zone,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                 'YYYYMMDD"T"HH24MISS"Z"' )::timestamptz)::timestamp without time zone,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                 IDAS.Narrative,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                 --cast( TRIM(PN.lastname)|| ',' ||TRIM(PN.firstname) as  character varying) RAName,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                 coalesce(IDAS.title,'') :: character varying RAName,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                 cast('' as character varying) EntityName,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                 cast(up.lastname ||', '|| up.firstname as character varying)   ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 coalesce(r.isreviewrequest,false),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 coalesce(rt.isupervisor,false) ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 r.insertedon,r.updatedon ,r.remarks,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                 cast(case lower(coalesce(rts.typedescription,'Pending'))                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                     when 'pending' then case ITDS.status when 10 then 'Assigned' else 'Draft' end  else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 case when tosecurityusersid = intakeuser and r.routingstatustypeid = 1 then 'Reopen' else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                     rts.typedescription end end as character varying)  ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                 cast('' as character varying) dispositiondescription,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                 cast('' as character varying) statusdescription,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                                  cast( case r.insertedon when null then '' else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                 case                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                     when  age(  now()at time zone 'utc')  - age(r.insertedon + time '02:00' )  > '0:00' then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                 cast( age( now() at time zone 'utc')  - age(  r.insertedon + time '02:00' ) as character varying(5))                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                      else   cast( age( now() at time zone 'utc')  - age(  r.insertedon  + time '02:00' ) as character varying(5)) end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                 end as character varying),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                 null::jsonb ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                 IDAS.updatedon ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 ITDS.teamtypekey ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 0, ITDS.ispreintake,ITDS.clwstatus                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
             FROM intakeservicerequest IDAS                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
             INNER JOIN intakeDAStatus ITDS on ITDS.intakenumber = IDAS.intakenumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
             LEFT JOIN  routing r ON r.objectid = IDAS.intakenumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 AND (r.activeflag =1 or r.activeflag = 1)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                 and r.eventcode ='INTR'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
             LEFT JOIN routingstatustype RTs ON RTs.sequencenumber = r.routingstatustypeid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                 and rts.activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
             LEFT JOIN teammemberroletype rt on rt.roletypekey = r.toroleid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 AND rt.activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
             INNER JOIN userprofile up on up.securityusersid = ITDS.intakeuser                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
            /* left JOIN intakeservicerequestactor as ISRA                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                  ON ISRA.intakeserviceid=IDAS.intakeserviceid and coalesce(isra.isprimary,false) =true                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
               and ISRA.activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
             Left JOIN actor as AR                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                 ON AR.actorid=ISRA.actorid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 and ar.activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
             Left JOIN person as PN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 ON PN.personid=AR.personid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                  and PN.activeflag =1*/                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
             WHERE IDAS.IntakeNumber like intakeno||'%'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                 AND (case v_status when 1 then  (ITDS.Status) =1 else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                 r.routingstatustypeid =v_status end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                 OR case ITDS.intakeuser  when v_UserSID then r.routingstatustypeid =6                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                      else  r.routingstatustypeid =v_status end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                     )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                 AND  IDAS.Activeflag = 1 and coalesce(ITDS.ispreintake,false) = false                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                 AND ( coalesce(r.tosecurityusersid,ITDS.intakeuser)  =v_UserSID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                    OR  case right(fromroleid,2) when 'IW' then ITDS.InsertedBy   =v_UserSID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                         else r.tosecurityusersid  =v_UserSID  end )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                 ORDER BY                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                  ( CASE sortorder when 'asc' then CASE sortcolumn when 'receiveddate' then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                   cast( IDAS.reportedtime    as character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                  when 'submittedworker' then  cast(up.lastname ||', '|| up.firstname as character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                     when 'intakenumber' then IDAS.intakenumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                  ELSE cast(IDAS.servicerequestnumber as   character varying) end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                   ELSE cast( IDAS.reportedarea  as character varying)  end)  asc,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                   ( CASE sortorder when 'desc' then CASE sortcolumn                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                    when 'receiveddate' then cast( IDAS.reportedtime    as character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                         when 'submittedworker' then  cast(up.lastname ||', '|| up.firstname as character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                    when 'intakenumber' then IDAS.intakenumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                  ELSE cast(IDAS.servicerequestnumber as   character varying) end  ELSE cast( IDAS.reportedarea  as character varying)  end )  desc)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                  ) t                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                  LIMIT pagesize OFFSET v_pageoffset ;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
            -- ORDER BY  IDAS.id DESC LIMIT pagesize OFFSET v_pageoffset ;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
         END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
  end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     

